-- GET and PATCH /api/v1/profile, GET /api/v1/keys and DELETE /api/v1/keys/{hash} join the fixed usage categories. Same non-destructive check as
-- 20261103000100_user_activity_usage.sql: NOT VALID applies to new writes and leaves historical rows alone.
ALTER TABLE open_index.api_usage
 DROP CONSTRAINT api_usage_endpoint_category,
 ADD CONSTRAINT api_usage_endpoint_category CHECK (endpoint IN ('GET /api/v1/search', 'GET /api/v1/records/{prefix}/{suffix}', 'GET /api/v1/records/{prefix}/{suffix}/comments', 'POST /api/v1/records/{prefix}/{suffix}/comments', 'GET /api/v1/records/{prefix}/{suffix}/vote', 'POST /api/v1/records/{prefix}/{suffix}/vote', 'DELETE /api/v1/records/{prefix}/{suffix}/vote', 'POST /api/v1/submit', 'GET /api/v1/forum', 'POST /api/v1/forum', 'GET /api/v1/forum/{id}', 'POST /api/v1/forum/{id}', 'POST /api/v1/forum/{id}/vote', 'POST /api/v1/forum/{id}/accept', 'GET /api/v1/prefixes', 'GET /api/v1/stats', 'POST /api/v1/keys/device', 'POST /api/v1/keys/token', 'GET /api/v1', 'GET /api/v1/openapi.json', 'GET /llms.txt', 'POST /mcp', 'GET /id/{prefix}/{suffix}', 'GET /sitemap.xml', 'GET /sitemap/{file}', 'GET /api/v1/users/{login}', 'GET /api/v1/profile', 'PATCH /api/v1/profile', 'GET /api/v1/keys', 'DELETE /api/v1/keys/{hash}')) NOT VALID;
